$date=auditDate(filter_input(INPUT_GET,'date'));list($start,$end)=auditWindow($date,'day');$dataset=auditDataset($db,$start,$end);$report=auditMeasure($dataset,$start,$end);
$changes=array();$countByLoom=array();
foreach($dataset['machines'] as $m){$previous=null;foreach($dataset['events'][(int)$m['IdTelaio']] as $event){$pattern=trim((string)$event['Armatura1']);
if($event['eventTimestamp']>=$start->getTimestamp()&&$event['eventTimestamp']<min($end->getTimestamp(),$dataset['now'])&&$previous!==null&&$previous!==''&&$pattern!==''&&$previous!==$pattern){$changes[]=array('loomId'=>(int)$m['IdTelaio'],'loomName'=>$m['NomeTelaio'],'previousPattern'=>$previous,'patternName'=>$pattern,'changedAt'=>date('Y-m-d H:i:s',(int)$event['eventTimestamp']));$id=(int)$m['IdTelaio'];$countByLoom[$id]=isset($countByLoom[$id])?$countByLoom[$id]+1:1;}
$previous=$pattern;}}
usort($changes,function($a,$b){return strcmp($b['changedAt'],$a['changedAt']);});?>
