<?php echo auditQualityHtml($report['quality']);?><section class="management-kpis"><article><span>Gözlenen desen değişimi</span><strong><?php echo count($changes);?></strong></article><article><span>Değişim olan tezgâh</span><strong><?php echo count($countByLoom);?></strong></article><article><span>Bir tezgâhta gözlenen en çok değişim</span><strong><?php echo $countByLoom?max($countByLoom):0;?></strong></article><article><span>Rapor tarihi</span><strong><?php echo $date->format('d.m.Y');?></strong></article></section>
<section class="management-panel"><header><h2>Desen değişim kayıtları</h2><small>Her satırda tezgâhın önceki deseni, yeni deseni ve değişimin alındığı zaman görünür.</small></header><div class="management-table-scroll"><table data-report-table><thead><tr><th>Tezgâh</th><th>Eski desen</th><th>Yeni desen</th><th>İlk gözlendiği zaman</th></tr></thead><tbody><?php foreach($changes as $change){?><tr><td><b><?php echo (int)$change['loomId'];?></b> <?php echo htmlspecialchars($change['loomName'],ENT_QUOTES,'UTF-8');?></td><td><?php echo htmlspecialchars($change['previousPattern'],ENT_QUOTES,'UTF-8');?></td><td><b><?php echo htmlspecialchars($change['patternName'],ENT_QUOTES,'UTF-8');?></b></td><td><?php echo htmlspecialchars($change['changedAt'],ENT_QUOTES,'UTF-8');?></td></tr><?php }if(!count($changes)){?><tr><td colspan="4" class="management-empty">Bu günün mevcut kayıtlarında desen değişimi gözlenmedi.</td></tr><?php }?></tbody></table></div></section>
